package me.xjanua.aitranswatch.repository;
import java.util.UUID; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import me.xjanua.aitranswatch.enums.VehicleStatus; import me.xjanua.aitranswatch.model.Vehicle;
public interface VehicleRepository extends JpaRepository<Vehicle, UUID> { boolean existsByLicensePlateIgnoreCase(String licensePlate); Page<Vehicle> findByStatus(VehicleStatus status, Pageable pageable); Page<Vehicle> findByLicensePlateContainingIgnoreCaseOrVehicleTypeContainingIgnoreCase(String plate,String type,Pageable pageable); Page<Vehicle> findByStatusAndLicensePlateContainingIgnoreCaseOrStatusAndVehicleTypeContainingIgnoreCase(VehicleStatus s1,String plate,VehicleStatus s2,String type,Pageable pageable); @org.springframework.data.jpa.repository.Query("select v.status, count(v) from Vehicle v group by v.status") java.util.List<Object[]> countByStatus(); }
